using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Tilemaps;using TimelessEchoes.NPC;
public static class SetupHabitatAnimals {
 public static object Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.isDirty)throw new Exception("Clean edit scene required");File.Copy(scene.path,"output/scene-review/Main.before-animals-disk.unity",true);EditorSceneManager.SaveScene(scene,"output/scene-review/Main.before-animals-live.unity",true);
 var home=GameObject.Find("Hometown").transform;var maps=home.GetComponentsInChildren<Tilemap>();var ground=maps.Single(t=>t.name=="BG -5");var cliffs=maps.Single(t=>t.name=="BG_Walkable -4");var root=new GameObject("Town Wildlife Habitats");root.transform.SetParent(home,false);Undo.RegisterCreatedObjectUndo(root,"Town wildlife");var log=new List<string>();
 Sprite[] Row(string path,int y){return AssetDatabase.LoadAllAssetsAtPath("Assets/Art/Packs/Cute_Fantasy/Animals/"+path).OfType<Sprite>().Where(s=>s.rect.y>=y&&s.rect.y<y+1).OrderBy(s=>s.rect.x).ToArray();}
 Sprite[] Clip(string name){var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/Art/Packs/Cute_Fantasy/Animals/Mouse/Black/"+name+".anim");var bind=AnimationUtility.GetObjectReferenceCurveBindings(clip).First();return AnimationUtility.GetObjectReferenceCurve(clip,bind).Select(k=>(Sprite)k.value).ToArray();}
 void Add(string name,HabitatAnimal.Habitat type,Vector2[] points,Sprite[] idle,Sprite[] move,float speed,float pauseMin,float pauseMax,float clearance){if(idle.Length==0||move.Length==0)throw new Exception("Missing frames: "+name);var go=new GameObject(name);go.transform.SetParent(root.transform,false);go.transform.localPosition=points[0];var sr=go.AddComponent<SpriteRenderer>();sr.sprite=idle[0];sr.sortingOrder=Mathf.RoundToInt(-sr.bounds.min.y*16);var animal=go.AddComponent<HabitatAnimal>();var so=new SerializedObject(animal);so.FindProperty("habitat").enumValueIndex=(int)type;so.FindProperty("ground").objectReferenceValue=ground;so.FindProperty("cliffs").objectReferenceValue=cliffs;so.FindProperty("speed").floatValue=speed;so.FindProperty("pauseSeconds").vector2Value=new Vector2(pauseMin,pauseMax);so.FindProperty("clearance").floatValue=clearance;so.FindProperty("framesPerSecond").floatValue=type==HabitatAnimal.Habitat.Air?10:6;
 var wp=so.FindProperty("waypoints");wp.arraySize=points.Length;for(int i=0;i<points.Length;i++)wp.GetArrayElementAtIndex(i).vector2Value=points[i];foreach(var tuple in new[]{("idleFrames",idle),("moveFrames",move)}){var a=so.FindProperty(tuple.Item1);a.arraySize=tuple.Item2.Length;for(int i=0;i<a.arraySize;i++)a.GetArrayElementAtIndex(i).objectReferenceValue=tuple.Item2[i];}so.ApplyModifiedPropertiesWithoutUndo();
 for(int i=0;i<points.Length;i++){var a=home.TransformPoint(points[i]);var b=home.TransformPoint(points[(i+1)%points.Length]);for(float t=0;t<=1;t+=.025f)if(!animal.IsSafe(Vector3.Lerp(a,b,t)))throw new Exception("Unsafe route "+name+" at "+Vector3.Lerp(a,b,t));}log.Add(name+" "+points[0]+" idle="+idle.Length+" moving="+move.Length);}
 Vector2[] LandRoute(Vector2 center){for(int radius=0;radius<5;radius++)for(int n=0;n<16;n++){var c=center+new Vector2(Mathf.Cos(n*Mathf.PI/8),Mathf.Sin(n*Mathf.PI/8))*radius*.5f;var points=new[]{c,c+new Vector2(.65f,.1f),c+new Vector2(.35f,-.45f)};bool safe=points.All(p=>{for(float x=-.4f;x<=.4f;x+=.2f)for(float y=-.4f;y<=.4f;y+=.2f){var w=home.TransformPoint(p+new Vector2(x,y));if(ground.GetSprite(ground.WorldToCell(w))?.name!="Grass_LightGreen_Fill"||cliffs.HasTile(cliffs.WorldToCell(w)))return false;}return true;});if(safe)return points;}throw new Exception("No safe land route at "+center);}
 Add("Duck - upper valley bend",HabitatAnimal.Habitat.Water,new[]{new Vector2(-25.5f,-32.5f),new Vector2(-24.5f,-33),new Vector2(-24,-34),new Vector2(-25,-33.5f)},Row("Duck/Duck_01.png",384),Row("Duck/Duck_01.png",352),.28f,2,6,.55f);
 Add("Duck - lower valley bend",HabitatAnimal.Habitat.Water,new[]{new Vector2(-20,-36),new Vector2(-19,-36.5f),new Vector2(-18.5f,-37),new Vector2(-20,-36.5f)},Row("Duck/Duck_02.png",384),Row("Duck/Duck_02.png",352),.24f,3,8,.55f);
 Add("Frog - west reeds",HabitatAnimal.Habitat.Land,LandRoute(new Vector2(-29,-32)),Row("Frog/Frog_01.png",96),Row("Frog/Frog_01.png",64),.7f,5,12,.3f);
 Add("Frog - east reeds",HabitatAnimal.Habitat.Land,LandRoute(new Vector2(-15,-32)),Row("Frog/Frog_02.png",96),Row("Frog/Frog_02.png",64),.65f,6,14,.3f);
 var butterflies=AssetDatabase.LoadAllAssetsAtPath("Assets/Art/Packs/Cute_Fantasy/Animals/Butterfly/Butterfly.png").OfType<Sprite>().ToArray();int bidx=0;foreach(var c in new[]{new Vector2(-37,-35),new Vector2(-1,-43),new Vector2(-18,8)}){var f=butterflies.Where(s=>s.name=="Butterfly_"+(bidx*4)||s.name=="Butterfly_"+(bidx*4+1)).OrderBy(s=>s.name).ToArray();Add("Butterfly flower patch "+(++bidx),HabitatAnimal.Habitat.Air,new[]{c,c+new Vector2(1,.5f),c+new Vector2(.4f,1.3f),c+new Vector2(-.6f,.6f)},f,f,.35f,1,3,.1f);}
 var bees=Row("Bee/Bee_Flying_Animation.png",18);foreach(var c in new[]{new Vector2(7,9),new Vector2(3,2)})Add("Bee - berry flowers",HabitatAnimal.Habitat.Air,new[]{c,c+new Vector2(.7f,.5f),c+new Vector2(1.3f,-.3f)},bees,bees,.55f,.5f,2,.1f);
 Add("Mouse - orchard cover",HabitatAnimal.Habitat.Land,LandRoute(new Vector2(-39,-17)),Clip("Eat"),Clip("Walk"),.85f,4,10,.25f);
 Add("Mouse - logging cover",HabitatAnimal.Habitat.Land,LandRoute(new Vector2(29,-24)),Clip("Idle"),Clip("Walk"),.9f,5,11,.25f);
 EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene,"output/scene-review/Main.after-animals-live.unity",true);File.WriteAllLines("output/scene-review/animal-placement.txt",log);return log;}}



